# Fix the typo and try again
output_7x7_plan = []
for i in range(0, 14, 2):
    row_7 = []
    for j in range(0, 14, 2):
        block = [test_input[i][j], test_input[i][j+1], test_input[i+1][j], test_input[i+1][j+1]]
        row_7.append(max(block))
    output_7x7_plan.append(row_7)

# Submit 7x7
{"action": "submit", "grid": output_7x7_plan}

# Fix the syntax and try again
def has_neighbor_diff(i, j, grid, rows, cols):
    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
        ni, nj = i + di, j + dj
        if 0 <= ni < rows and 0 <= nj < cols:
            if grid[ni][nj] != grid[i][j]:
                return True
    return False

mark_boundary2 = []
for i in range(14):
    row_marked = []
    for j in range(14):
        diff = has_neighbor_diff(i, j, test_input, 14, 14)
        row_marked.append(1 if diff else 0)
    mark_boundary2.append(row_marked)

print("Boundary marks count:", sum(sum(row) for row in mark_boundary2))

# Submit boundary detection
{"action": "submit", "grid": mark_boundary2}

# I'm near my cap. Let me try one more approach:
# Output values represent "change" relative to neighbors or some baseline.

# Try: output = difference between cell and top-left corner value
top_left = test_input[0][0]  # 2

diff_from_topleft = []
for i in range(14):
    row = []
    for j in range(14):
        diff = test_input[i][j] - top_left
        # Take absolute value or keep signed
        if diff == 0:
            row.append(0)
        elif diff > 0:
            row.append(test_input[i][j])  # Keep original if positive diff
        else:
            row.append(0)
    diff_from_topleft.append(row)

# Submit this variant
{"action": "submit", "grid": diff_from_topleft}

